 if($file.Name -eq 'Build.Tests.trx'){
  $evidence.P1Results=@($results|Where-Object testName -Match 'SessionLifeUnitGate|TestTarget_ExcludesPluginIntegrationFromUnitInventory'|Select-Object testName,outcome)
 }
