$m=Get-Content docs/receipts/sessionlife-completion/20260928-p0-r3/acceptance-manifest.json -Raw | ConvertFrom-Json
[xml]$nunit=Get-Content TestResults/p2-unit-legion-20261002T202158Z/pester/results.xml -Raw
$nativeNames=@($nunit.SelectNodes('//test-case') | ForEach-Object {$_.name})
$rows=@($m.requirementAcceptanceCoverage | Where-Object requirementId -Match '^(FR|TR|TEST)-MCP-SESSIONLIFE-00[123]$')
foreach($r in $rows){
