$e.traceCounts=[ordered]@{rows=$rows.Count;withConcreteTests=@($rows | Where-Object {$_.criterionSpecificExistingTests.Count -gt 0}).Count;withoutConcreteTests=@($rows | Where-Object {$_.criterionSpecificExistingTests.Count -eq 0}).Count;frRows=@($rows | Where-Object requirementId -Like 'FR-*').Count;frWithConcreteTests=@($rows | Where-Object {$_.requirementId -like 'FR-*' -and $_.criterionSpecificExistingTests.Count -gt 0}).Count;trRows=@($rows | Where-Object requirementId -Like 'TR-*').Count;trWithConcreteTests=@($rows | Where-Object {$_.requirementId -like 'TR-*' -and $_.criterionSpecificExistingTests.Count -gt 0}).Count;todoRows=$m.todoAcceptanceRows.Count;todoNotAccepted=@($m.todoAcceptanceRows|Where-Object acceptanceState -EQ 'not-accepted').Count;uniqueTodoIds=@($m.scope.todoIds|Sort-Object -Unique).Count}
$e.mappingFreeze=$m.mappingFreeze
